import{_ as i,o as s,c as n,j as t,a as o,t as r,a1 as h}from"./chunks/framework.90UQlTmt.js";const k=JSON.parse('{"title":"Troubleshooting","description":"","frontmatter":{"title":"Troubleshooting"},"headers":[],"relativePath":"guide/troubleshooting.md","filePath":"guide/troubleshooting.md","lastUpdated":1786660168000}'),d={name:"guide/troubleshooting.md"},l={id:"frontmatter-title",tabindex:"-1"};function c(a,e,p,u,g,b){return s(),n("div",null,[t("h1",l,[o(r(a.$frontmatter.title)+" ",1),e[0]||(e[0]=t("a",{class:"header-anchor",href:"#frontmatter-title","aria-label":'Permalink to "{{ $frontmatter.title }}"'},"​",-1))]),e[1]||(e[1]=h(`<h2 id="nothing-is-being-cached" tabindex="-1">Nothing is being cached <a class="header-anchor" href="#nothing-is-being-cached" aria-label="Permalink to &quot;Nothing is being cached&quot;">​</a></h2><p><strong>Check <code>X-Cache</code> first.</strong> Set <code>enableXCacheHeaders: true</code> and look at the response header. It tells you which of three things is happening.</p><p><code>HITPASS</code> — the request bypassed the cache deliberately. The default <code>hitpass</code> does this for anything carrying an <code>authorization</code> or <code>cookie</code> header, which includes every request a browser makes while logged into the admin panel. Test with <code>curl</code>, or read <a href="./caching/keys.html#useauth">per-caller keys</a>.</p><p><code>MISS</code> every time — the response is being refused. The plugin will not store a response that is empty, not <code>2xx</code>, a stream, sets a <code>Set-Cookie</code>, or says <code>Cache-Control: no-store</code>/<code>private</code>. See <a href="./reference/config.html#what-is-never-cached">what is never cached</a>.</p><p>No header at all — the route is not cached. The middleware was never attached to it, which is a configuration problem rather than a runtime one. Open <strong>Settings → REST Cache</strong> and look at the routes listed for the content type: what you see there is what was actually resolved. A path that does not appear did not match anything Strapi registered.</p><h2 id="a-route-i-configured-is-not-listed" tabindex="-1">A route I configured is not listed <a class="header-anchor" href="#a-route-i-configured-is-not-listed" aria-label="Permalink to &quot;A route I configured is not listed&quot;">​</a></h2><p>The <code>path</code> must be the path <strong>as Strapi registered it</strong>, including the API prefix — <code>/api/articles/slug/:slug</code>, not <code>/articles/slug/:slug</code>.</p><p>Enable <a href="#debug-mode">debug mode</a>; the plugin logs every configured route it could not match:</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>[WARNING] route &quot;[GET] /articles/slug/:slug&quot; not registered in strapi, ignoring...</span></span></code></pre></div><h2 id="stale-content-after-a-write" tabindex="-1">Stale content after a write <a class="header-anchor" href="#stale-content-after-a-write" aria-label="Permalink to &quot;Stale content after a write&quot;">​</a></h2><p>Invalidation runs from the document service by default, which covers REST, GraphQL, the content manager, Content Releases and any <code>strapi.documents()</code> call. Content changed <strong>directly in the database</strong> bypasses all of that, and nothing can observe it. Purge manually — see <a href="./invalidation/purging.html">Purging</a>.</p><p>If the write did go through Strapi, check that <code>enableDocumentServiceMiddleware</code> is on in <strong>Settings → REST Cache</strong>. With it off, the plugin falls back to route-injected middleware, which only sees writes that arrive over a route it knows about.</p><h2 id="everything-expires-far-too-late" tabindex="-1">Everything expires far too late <a class="header-anchor" href="#everything-expires-far-too-late" aria-label="Permalink to &quot;Everything expires far too late&quot;">​</a></h2><p><code>maxAge</code> is <strong>milliseconds</strong>. <code>3600</code> is 3.6 seconds, not an hour; <code>3600000</code> is an hour. The dashboard renders the resolved value in human units (<code>1h</code>, <code>30m</code>), which is the quickest way to confirm what a content type actually has.</p><h2 id="purging-clears-more-than-i-expected" tabindex="-1">Purging clears more than I expected <a class="header-anchor" href="#purging-clears-more-than-i-expected" aria-label="Permalink to &quot;Purging clears more than I expected&quot;">​</a></h2><p><code>clearRelatedCache</code> is on by default: purging a content type also purges those related to it through relations and components, transitively. The dashboard shows the count per row (&quot;Also purges 4 related types&quot;). Turn it off if you would rather accept staleness in related responses.</p><h2 id="redis-entries-are-written-but-never-purged" tabindex="-1">Redis: entries are written but never purged <a class="header-anchor" href="#redis-entries-are-written-but-never-purged" aria-label="Permalink to &quot;Redis: entries are written but never purged&quot;">​</a></h2><p>Check that <code>strategy.keysPrefix</code> matches the <code>keyPrefix</code> your Redis connection uses. The plugin filters and strips its own prefix when enumerating keys; a mismatch means it enumerates nothing and every purge silently does nothing.</p><h2 id="debug-mode" tabindex="-1">Debug mode <a class="header-anchor" href="#debug-mode" aria-label="Permalink to &quot;Debug mode&quot;">​</a></h2><div class="language-js vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">js</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">strategy</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: {</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">  debug</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">true</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">,</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">}</span></span></code></pre></div><p>This enables the plugin&#39;s <code>debug</code> namespace, which logs route registration, every cache hit and miss with its key, and every purge with the number of keys removed. You can also enable it without changing configuration:</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">DEBUG</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">=</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">strapi:plugin-rest-cache</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;"> npm</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> run</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> develop</span></span></code></pre></div><h2 id="getting-help" tabindex="-1">Getting help <a class="header-anchor" href="#getting-help" aria-label="Permalink to &quot;Getting help&quot;">​</a></h2><p>Open an issue at <a href="https://github.com/strapi-community/plugin-rest-cache/issues" target="_blank" rel="noreferrer">strapi-community/plugin-rest-cache</a>. Include your <code>rest-cache</code> configuration, your Strapi and Node versions, and the <code>X-Cache</code> header for the request that behaved unexpectedly — that header usually identifies the problem on its own.</p>`,24))])}const y=i(d,[["render",c]]);export{k as __pageData,y as default};
